params.add('boss_width', 24.37, min=8.0, max=44.0, expression='width * 0.285', semantic_type='boss_width')
params.add('cut_depth', 1.6, min=0.5, max=6.0, semantic_type='pocket_depth')
params.add('fillet_radius', 0.31, min=0.05, max=0.8, semantic_type='fillet_radius')
params.add('height', 54.8, min=12, max=80, semantic_type='overall_height')
params.add('hole_offset_x', 27.36, min=4.0, max=42.0, expression='width * 0.32', semantic_type='hole_spacing')
params.add('hole_offset_y', 15.34, min=3.0, max=30.0, expression='height * 0.28', semantic_type='hole_spacing')
params.add('hole_radius', 1.82, min=1, max=8, semantic_type='hole_radius')
params.add('slot_height', 4.23, min=2.0, max=18.0, expression='boss_height * 0.292', semantic_type='pocket_width')
params.add('slot_width', 9.21, min=4.0, max=28.0, expression='boss_width * 0.378', semantic_type='pocket_width')
params.add('thickness', 7, min=3, max=25, semantic_type='thickness')
params.add('width', 85.5, min=20, max=120, semantic_type='overall_width')

part = Part('flluma_0090147', category='face_feature_service_cover', parameters=params, seed=20350661, sample_id='flluma_0090147', units='mm')
plate = part.plate(name='service_cover_plate', width=params['width'], height=params['height'], thickness=params['thickness'], semantic_type='base_plate')
boss_profile = part.sketch_on_face(name='service_cover_boss_profile', target=plate.top_face(), profile='rectangle', width=params['boss_width'], height=params['boss_height'], semantic_type='boss_profile')
face_add = part.extrude_on_face(name='service_cover_raised_boss', target=plate.top_face(), sketch=boss_profile, height=params['boss_lift'], operation='join', semantic_type='face_boss')
pocket_profile = part.sketch_on_face(name='service_cover_window_profile', target=face_add.top_face(), profile='rectangle', width=params['slot_width'], height=params['slot_height'], semantic_type='pocket_profile')
face_cut = part.extrude_on_face(name='service_cover_window_cut', target=face_add.top_face(), sketch=pocket_profile, depth=params['cut_depth'], operation='cut', semantic_type='face_cut')
holes = part.hole_pattern(name='service_cover_mounting_holes', target=face_cut.top_face(), radius=params['hole_radius'], depth='through', positions=[[-27.36, -15.34], [27.36, -15.34], [-27.36, 15.34], [27.36, 15.34]], semantic_type='mounting_hole')
fillet = part.fillet(name='service_cover_boss_edge_break', target=holes.top_outer_edges(), radius=params['fillet_radius'], semantic_type='edge_break')

__all__ = ['part']
